+// resolveClientAddr resolves the real client IP address by inspecting request headers
+// according to the engine's trusted proxy and platform configuration.
+func (engine *Engine) resolveClientAddr(req *http.Request, remoteIP net.IP) string {
+	// Check if we're running on a trusted platform, continue running backwards if error
+	if engine.TrustedPlatform != "" {
+		if addr := req.Header.Get(engine.TrustedPlatform); addr != "" {
+			return addr
+		}
+	}
+
+	// Legacy "AppEngine" flag
+	if engine.AppEngine {
+		log.Println(`The AppEngine flag is going to be deprecated. Please check issues #2723 and #2739 and use 'TrustedPlatform: gin.PlatformGoogleAppEngine' instead.`)
