+			return addr
+		}
+	}
+
+	if remoteIP == nil {
+		return ""
+	}
+
+	trusted := engine.isTrustedProxy(remoteIP)
+
+	if trusted && engine.ForwardedByClientIP && engine.RemoteIPHeaders != nil {
+		for _, headerName := range engine.RemoteIPHeaders {
+			ip, valid := engine.validateHeader(req.Header.Get(headerName))
+			if valid {
+				return ip
+			}
+		}
+	}
+	return remoteIP.String()
